import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import vm from 'node:vm';
import { buildBundle, buildPageBundle } from '../../scripts/build-page-bundle.mjs';

const BUNDLE_HEADER = '// Generated by scripts/build-page-bundle.mjs. Do not edit by hand.';

const committedBundleText = readFileSync(new URL('../src/page/bundle.js', import.meta.url), 'utf8');
const loaderText = readFileSync(new URL('../loader.js', import.meta.url), 'utf8');

/** Git may check text files out with CRLF; the bundle content is compared with LF endings. */
function normalizeLineEndings(text) {
  return text.replace(/\r\n/g, '\n');
}

// --- The committed page bundle and the loader. ---

test('committed page bundle equals a fresh build (run: node scripts/build-page-bundle.mjs)', () => {
  assert.equal(normalizeLineEndings(committedBundleText), buildPageBundle());
});

test('page bundle starts with the generated-file header', () => {
  assert.ok(normalizeLineEndings(committedBundleText).startsWith(`${BUNDLE_HEADER}\n`));
});

test('page bundle has no import or export statements', () => {
  // Dynamic import() and import.meta are rejected by the bundler itself (tests below), and
  // import.meta would also fail the classic-script compile check. JSDoc type comments such as
  // {import('./x.js').Type} are allowed to stay.
  assert.doesNotMatch(committedBundleText, /^\s*(import|export)\s/m);
});

test('page bundle compiles as a classic script', () => {
  assert.doesNotThrow(() => new vm.Script(committedBundleText, { filename: 'bundle.js' }));
});

test('page bundle runs in a fake page and completes the storage round trip', async () => {
  const infoMessages = [];
  const errorMessages = [];
  const messageListeners = new Set();
  const storedItems = new Map();

  const fakeWindow = {
    addEventListener(type, listener) {
      if (type === 'message') messageListeners.add(listener);
    },
    removeEventListener(type, listener) {
      if (type === 'message') messageListeners.delete(listener);
    },
    // Plays the storage host: answers each storage request asynchronously.
    postMessage(data) {
      if (data?.kind !== 'request') return;
      const payload = data.payload ?? {};
      let result = {};
      if (data.operation === 'set') for (const [key, value] of Object.entries(payload.items)) storedItems.set(key, value);
      if (data.operation === 'get') result = Object.fromEntries(payload.keys.filter((key) => storedItems.has(key)).map((key) => [key, storedItems.get(key)]));
      if (data.operation === 'remove') for (const key of payload.keys) storedItems.delete(key);
      const response = { channel: data.channel, kind: 'response', requestId: data.requestId, result, errorText: null };
      queueMicrotask(() => {
        for (const listener of [...messageListeners]) listener({ source: fakeWindow, data: response });
      });
    },
  };

  let roundTripFinished;
  const roundTripFinishedPromise = new Promise((resolve) => {
    roundTripFinished = resolve;
  });
  const context = vm.createContext({
    window: fakeWindow,
    document: {},
    location: { pathname: '/' },
    console: {
      info: (message) => {
        infoMessages.push(message);
        roundTripFinished();
      },
      error: (message) => errorMessages.push(message),
    },
    // Timers are recorded but never fire, so the test cannot depend on wall-clock time.
    setTimeout: () => 0,
    clearTimeout: () => {},
    queueMicrotask,
  });

  new vm.Script(committedBundleText, { filename: 'bundle.js' }).runInContext(context);
  await roundTripFinishedPromise;

  assert.deepEqual(infoMessages, ['lingotube: page ready, storage ok']);
  assert.deepEqual(errorMessages, []);
  assert.equal(storedItems.size, 0);
});

test('loader.js does not inject the page bundle itself', () => {
  assert.doesNotMatch(loaderText, /getURL\(/);
  assert.doesNotMatch(loaderText, /createElement\(\s*['"]script['"]\s*\)/);
  assert.doesNotMatch(loaderText, /appendChild/);
});

test('manifest declares the page bundle as a MAIN-world content script', () => {
  const manifest = JSON.parse(readFileSync(new URL('../manifest.json', import.meta.url), 'utf8'));
  const pageBundleEntries = manifest.content_scripts.filter((entry) => entry.world === 'MAIN');
  assert.equal(pageBundleEntries.length, 1);
  assert.deepEqual(pageBundleEntries[0].js, ['src/page/bundle.js']);
  assert.deepEqual(pageBundleEntries[0].matches, ['https://www.youtube.com/*']);
  assert.equal(pageBundleEntries[0].run_at, 'document_idle');
});

// --- The bundler itself, on throwaway module trees. ---

/** Writes the given files under a fresh temp folder, bundles `entry`, and removes the folder. */
function bundleFixture(files, entry = 'main.js') {
  const sourceRoot = mkdtempSync(join(tmpdir(), 'lingotube-bundle-'));
  try {
    for (const [relativePath, text] of Object.entries(files)) {
      const filePath = join(sourceRoot, relativePath);
      mkdirSync(dirname(filePath), { recursive: true });
      writeFileSync(filePath, text);
    }
    return buildBundle({ entryFile: join(sourceRoot, entry), sourceRoot });
  } finally {
    rmSync(sourceRoot, { recursive: true, force: true });
  }
}

/** Runs a bundle that reports through `report(...)` and returns copies of what it reported. */
function runFixtureBundle(bundleText) {
  const reports = [];
  vm.runInNewContext(bundleText, { report: (value) => reports.push(structuredClone(value)) });
  return reports;
}

test('bundler resolves named, aliased, namespace and re-exported bindings', () => {
  const bundleText = bundleFixture({
    'main.js': [
      "import { double, LIMIT as limit } from './lib/math.js';",
      "import * as words from './lib/words.js';",
      "import { shout } from './lib/index.js';",
      'report(double(limit));',
      "report(words.greet('a'));",
      "report(shout('b'));",
      'report(Object.keys(words).sort().join(","));',
    ].join('\n'),
    'lib/math.js': 'export const LIMIT = 21;\nexport function double(value) {\n  return value * 2;\n}\n',
    'lib/words.js': [
      'function greet(name) {',
      '  return `hi ${name}`;',
      '}',
      'class Shouter {',
      '  shout(text) {',
      '    return text.toUpperCase();',
      '  }',
      '}',
      'export { greet, Shouter as Loud };',
    ].join('\n'),
    'lib/index.js': "import { Loud } from './words.js';\nexport { greet } from './words.js';\nexport async function unused() {}\nexport const shout = (text) => new Loud().shout(text);\n",
  });
  assert.deepEqual(runFixtureBundle(bundleText), [42, 'hi a', 'B', 'Loud,greet']);
});

test('bundler keeps colliding top-level names of different modules apart', () => {
  const bundleText = bundleFixture({
    'main.js': "import { first } from './a.js';\nimport { second } from './b.js';\nconst LABEL = 'main';\nreport([first(), second(), LABEL]);\n",
    'a.js': "const LABEL = 'a';\nexport function first() {\n  return LABEL;\n}\n",
    'b.js': "const LABEL = 'b';\nexport function second() {\n  return LABEL;\n}\n",
  });
  assert.deepEqual(runFixtureBundle(bundleText), [['a', 'b', 'main']]);
});

test('bundler evaluates each module once, dependencies first', () => {
  const bundleText = bundleFixture({
    'main.js': "import { a } from './a.js';\nimport { b } from './b.js';\nreport('main');\n",
    'a.js': "import { shared } from './shared.js';\nreport('a');\nexport const a = shared;\n",
    'b.js': "import { shared } from './shared.js';\nreport('b');\nexport const b = shared;\n",
    'shared.js': "report('shared');\nexport const shared = 1;\n",
  });
  assert.deepEqual(runFixtureBundle(bundleText), ['shared', 'a', 'b', 'main']);
});

test('bundler ignores import-like text in comments, strings, templates and regexes', () => {
  const bundleText = bundleFixture({
    'main.js': [
      "/** @typedef {import('./types.js').Thing} Thing */",
      "// import { nothing } from './missing.js';",
      "const text = \"export const fake = 1; import x from 'y'\";",
      'const template = `export ${text.length > 0 ? `import` : ""}`;',
      'const pattern = /import\\s+export/;',
      'const options = { import: 1, export: 2 };',
      'report([pattern.test("import  export"), template, options.import + options.export]);',
    ].join('\n'),
  });
  assert.deepEqual(runFixtureBundle(bundleText), [[true, 'export import', 3]]);
});

const unsupportedModuleSources = {
  'a default import': "import thing from './other.js';\n",
  'a default export': 'export default 1;\n',
  'export *': "export * from './other.js';\n",
  'import.meta': 'const where = import.meta.url;\n',
  'a dynamic import': "const later = import('./other.js');\n",
  'export let': 'export let counter = 0;\n',
  'export var': 'export var counter = 0;\n',
  'a destructured export': 'export const { a, b } = {};\n',
  'several declarators in one export': 'export const a = 1, b = 2;\n',
  'a reassigned export': 'export function thing() {}\nthing = null;\n',
  'an incremented export': 'export const count = 1;\nfunction bump() {\n  count++;\n}\n',
  'a bare specifier': "import { thing } from 'some-package';\n",
  'a specifier without .js': "import { thing } from './other';\n",
};

for (const [description, mainSource] of Object.entries(unsupportedModuleSources)) {
  test(`bundler fails loudly on ${description}`, () => {
    assert.throws(
      () => bundleFixture({ 'main.js': mainSource, 'other.js': 'export const thing = 1;\n' }),
      /build-page-bundle/,
    );
  });
}

test('bundler fails loudly on an import of a missing export', () => {
  assert.throws(
    () => bundleFixture({ 'main.js': "import { absent } from './other.js';\n", 'other.js': 'export const thing = 1;\n' }),
    /build-page-bundle: .*absent/,
  );
});

test('bundler fails loudly on an import cycle', () => {
  assert.throws(
    () =>
      bundleFixture({
        'main.js': "import { a } from './a.js';\n",
        'a.js': "import { b } from './b.js';\nexport const a = 1;\n",
        'b.js': "import { a } from './a.js';\nexport const b = 2;\n",
      }),
    /build-page-bundle: .*cycle/,
  );
});

test('bundler fails loudly when a module already uses a generated binding name', () => {
  assert.throws(
    () =>
      bundleFixture({
        'main.js': "import { thing } from './other.js';\nconst bundledModule0Exports = thing;\n",
        'other.js': 'export const thing = 1;\n',
      }),
    /build-page-bundle: .*bundledModule0Exports/,
  );
});
